export function stdpMemoryUpdate(memory, retrievals) {
  retrievals.forEach(({ id, timestamp }) => {
    if (memory[id]) {
      const timeDelta = Date.now() - timestamp;
      memory[id].strength += 1 / (1 + Math.exp(-timeDelta / 1000));
    }
  });
  return memory;
}